"""Reproduce only #296 localization entries; no asset/audio bootstrap."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
PAIRS={'dimension': ('Где искать: %s', 'Dimension: %s'), 'overworld': ('Обычный мир', 'Overworld'), 'nether': ('Незер', 'Nether'), 'end': ('Энд', 'The End'), 'known': ('Область поиска известна.', 'Search area known.'), 'found': ('Место найдено.', 'Target discovered.'), 'completed': ('Поиск завершён.', 'Search completed.'), 'unknown': ('Область пока не определена. Достоверных координат нет.', 'The search area is not defined yet. No reliable coordinates.'), 'expired': ('Подсказка устарела. Запросите актуальные сведения.', 'This hint has expired. Request an update.'), 'other_dimension': ('Цель в другом измерении. Перейдите в указанное измерение.', 'The target is in another dimension. Travel to the dimension shown.'), 'center': ('Примерный центр: X %s, Z %s', 'Approximate center: X %s, Z %s'), 'radius': ('Радиус поиска: %s блоков', 'Search radius: %s blocks'), 'bounds_x': ('Границы по X: от %s до %s', 'X bounds: %s to %s'), 'bounds_z': ('Границы по Z: от %s до %s', 'Z bounds: %s to %s'), 'circle': ('Ищите цель внутри указанной круглой области.', 'Search for the target inside this circular area.'), 'bounds_note': ('Границы X/Z описывают охватывающий прямоугольник. Его углы не входят в круг.', 'The X/Z bounds enclose the circle. The corners are outside the search area.'), 'world_edge': ('Границы ограничены краем мира; исходный радиус сохранён.', 'Bounds are clipped to the world edge; the original radius is unchanged.'), 'inside': ('Вы внутри области. Осмотрите местность.', 'You are inside the area. Explore your surroundings.'), 'outside': ('Вы вне области. До её края примерно %s блоков.', 'You are outside the area, about %s blocks from its edge.'), 'point': ('Известная точка: X %s, Y %s, Z %s', 'Known location: X %s, Y %s, Z %s'), 'point_known': ('Место известно.', 'Location known.'), 'open': ('Где искать', 'Where to search'), 'page': ('Место %s из %s', 'Location %s of %s'), 'ended': ('Отслеживание завершено. Координаты больше не актуальны.', 'Tracking has ended. These coordinates are no longer current.')}
def apply():
 for index,locale in enumerate(('ru_ru','en_us')):
  p=ROOT/'src/main/resources/assets/slavicmyths/lang'/f'{locale}.json'
  data=json.loads(p.read_text(encoding='utf-8'))
  data.update({'navigation.search.'+key:value[index] for key,value in PAIRS.items()})
  p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
if __name__=='__main__':apply()
